# Builds part_leapfrog.json from the audit reasoning + out_leapfrog.json numbers (run after check_leapfrog.mjs).
import json, os
here = os.path.dirname(os.path.abspath(__file__))
o = json.load(open(os.path.join(here, 'out_leapfrog.json')))
S = o['scenarios']; V = o['variants']; sd = o['seeds']; en = o['endurance']; cap = o['capture']
def a(id): return S[id]['audit']
def m(id, k): return S[id]['metricsRerun'][k]['value']
F = []
def f(i, sev, claim, ev, fix, fx): F.append({'id': f'LF-{i:02d}', 'concept': 'leapfrog', 'severity': sev, 'claim': claim, 'evidence': ev, 'recommendedFix': fix, 'fixable': fx})

f(1, 'major', 'jitterRms 1.34 °/s (nominal) / 2.72 °/s (short) passes the ≤3 °/s footage-stability criterion.',
  f"The angular metric is not normalised to the frame. Leapfrog films through a ~6° vertical crop (median cropV nominal {a('nominal')['cropVmedDeg']}°, short {a('short')['cropVmedDeg']}°), so 1.34 °/s = {a('nominal')['jitterPctFramePerS']} % of frame height per second (short turns {a('short')['jitterPctFramePerS']} %/s; independent footageStability subject {a('nominal')['footageStability']['subjectRms']} / {a('short')['footageStability']['subjectRms']} °/s = {a('nominal')['fsSubjectPctFramePerS']} / {a('short')['fsSubjectPctFramePerS']} %/s). The 3 °/s line was calibrated on chase framings with ~25–30° crops (≈10–12 %/s). In addition, the glider is a point mass: airframe roll/pitch/yaw in turbulence is not simulated and the 10 g 2-axis turret is credited with an ASSUMED 0.5 °/s residual and perfect world stabilisation (roll unstabilised in hardware). Re-computed footageStability matches the claimed values in all 15 scenarios (e.g. nominal 1.249/0.898).",
  'Report jitter in % of output frame height per second (or px/s) for all concepts; add airframe attitude dynamics + a turret disturbance-rejection model; loosen framing (fill 0.35 instead of 0.5) for the lead flight.', 'yes')

f(2, 'major', 'Native resolution 6144 rows (full 50 MP 1/1.56″ readout) gives a 300 px range of ~66 m, which carries avail and the approach share.',
  f"Quad-Bayer 50 MP sensors (IMX766 class) record video binned (≈12.5 MP, ~3072 rows) or by in-sensor remosaic crop with reduced effective resolution (OVT OV64C brief: hardware remosaic + 2× crop at 16 MP, https://www.ovt.com/sensors/OV64C; IMX766 default binned output, https://zentalk.asus.com/t5/zenfone-9/50mp-camera-resolution/td-p/190258). Re-run with camRows 3072: nominal avail {V['rows3072_binned']['nominal']['avail']} % (FAIL), approach share {V['rows3072_binned']['nominal']['frontShare']} %, short {V['rows3072_binned']['short']['avail']} %, crossgust {V['rows3072_binned']['crossgust']['avail']} %. With ≈0.7 effective linear resolution (4300 rows): nominal {V['rows4300_remosaic']['nominal']['avail']} %, short {V['rows4300_remosaic']['short']['avail']} % (FAIL), crossgust {V['rows4300_remosaic']['crossgust']['avail']} %.",
  'Specify a sensor/ISP that reads the needed window at full resolution at 30 fps (e.g. a 1″-type 20 MP with crop readout) or a longer lens with tighter turret pointing; or shorten the perch gap (fewer but closer shots); re-run with effective rows.', 'yes')

f(3, 'major', '125 g flying mass (airframe 42, camera+ISP 13, turret+periscope 10, battery 20, hoop 5 g …) keeps KE ≤14.9 J at a 15 m/s ground-speed cap.',
  "Audit budget from real parts: folding 0.70 m airframe with V-tail, wing-tip skids, belly claws, spring hinges ≈48 g; 1104 motor+4.5″ folding prop+ESC 11 g; FC/IMU/GNSS/UWB/radio/ToF ≈10 g; actuators (4 servos + claw, mast and hoop-shift actuators) ≈16 g; 50 MP tele module ≈4 g + a compute board able to read 50 MP, encode 4K and run tracking ≈11–16 g (ModalAI VOXL 2 Mini 11 g, 0.5–8 W, https://www.modalai.com/products/voxl-2-mini); 2-axis turret + 0.35 m periscope ≈20–25 g (smallest FPV gimbal, CaddxFPV GM1, is 1-axis and 16 g, https://oscarliang.com/caddxfpv-camera-gimbals; a 4K gimbal-less camera RunCam Thumb 2 is 27 g); 1S 3.7 Wh high-C pack ≈24 g (GNB 2S 720 mAh HV = 36 g ≈150 Wh/kg) + self-heating foil; hoop+lanyard+shift ≈7 g; wiring 5 g → ≈160–175 g. At 175 g the KE cap becomes 13.0 m/s (√(2·14.9/0.175)); keeping 15 m/s gives keMax " + f"{V['mass175_cap15']['nominal']['keMax']} J (FAIL). With 175 g and a 13 m/s cap the lead envelope falls from vTarget 14 to 13 m/s, nominal ends with a fall-behind event, touchdown KE exceeds the 3 J design target in every scenario; combined realistic variant (175 g, cd0 0.05, camera 3.5 W, 4300 rows): nominal avail {V['audit_realistic']['nominal']['avail']} % FAIL, short {V['audit_realistic']['short']['avail']} % FAIL, endurance {V['audit_realistic']['nominal']['endurance']} min.",
  'Publish a component-level BOM with sourced masses; drop the periscope (perch-height camera on a fixed short mast) or the active hoop; re-derive vCapG from the real mass; keep the 250 g C0 margin.', 'yes')

f(4, 'major', 'ops = 2 per run (toss + snatch); lift-queue stow counted as 0 actions.',
  "criteria.js ops counts 'deploy/launch, stow/land, battery swap, recovery'. The user sequence has three distinct actions: draw+toss (deploy), pole-basket snatch at the run-out (recovery, while moving), unhook from the pole + fold wings + retract hoop/periscope + holster (stow, 6 s standstill already counted in setupTime but 0 actions). Recounted ops = 3 → FAIL (≤2) in every scenario; standstill 4 + 10–15 s gloved stow = 14–19 s still passes ≤30 s. Stranded cases (powder, motor fail, perch failure) are ops 3–4 + detour.",
  'Make the snatch the stow (hoop pulls the glider straight into a pole-mounted or holster sleeve) or count honestly as 3; measure gloved stow time.', 'yes')

f(5, 'major', 'Other skiers are protected by landing-site selection and early hops; KE ≤14.1 J; resort approval is just needed.',
  f"Only one neighbour on a straight track is simulated (nbMin {m('neighbour','nbMin') if 'nbMin' in S['neighbour']['metricsRerun'] else 4.645} m). The device repeatedly lands and sits on the open piste 9–16 m off the rider's line (the lane of other skiers, not the piste edge on a ≤35 m piste), flies at ≤15 m/s, 3 m above snow, approaching downhill skiers from BEHIND (they cannot see it), and the capture perch is placed on the rider's line at the run-out, i.e. the converging lift-approach area. A skier hitting or catching an edge on a 125–175 g perched object is not modelled. Vail Resorts prohibits drones on/over all its properties without written permission, enforced by pass revocation (https://www.vail.com/the-mountain/about-the-mountain/safety/drones.aspx); Alta/Brian Head similar (https://www.skiutah.com/blog/utah-resort-drone-policies). EU A1: C0 may overfly uninvolved persons but never assemblies (UAS.OPEN.020, https://regulatorylibrary.caa.co.uk/2019-947/Content/map/00320_UAS.OPEN.020_UAS_operations_in_subcategory_A1.htm); an unpowered glider is still an unmanned aircraft.",
  'Model a Poisson field of other skiers (density by piste class) and report collision/near-miss rates; restrict perching to the outer 3 m of the piste; add a no-fly/no-perch rule when skiers are within N m downslope; seek a written resort pilot permission before any field work.', 'no')

f(6, 'major', "Fault scenarios (powder, motorfail) are 'judged on safety only' and the concept is presented as passing all criteria.",
  f"Powder: avail {m('powder','avail')} %, approach {m('powder','frontShare')} %, ops 3, stranded on the piste ~9 m off the line (manual recovery); motorfail: avail {m('motorfail','avail')} %, ops 3. These are not rare faults: soft snow at the piste side after any snowfall, wind-loaded edges and afternoon slush cover the very lane (9–16 m off the rider's line) the glider perches on; ice the opposite failure — with claws not biting (μ≈0.3) a 6 m/s touchdown slides ≈{o['perching']['slideFrom6ms_iceMu0_3_m']:.0f} m on 15° instead of ≈{o['perching']['slideFrom6ms_m']:.1f} m. Snow condition is an operating-envelope variable, not a fault.",
  'Treat powder/slush/ice as envelope scenarios with harmonised pass/fail; add an in-air hold (lead-only) mode when the snow under the lane is soft, and report the share of resort-days on which perching is possible.', 'yes')

f(7, 'major', 'Post-stall perching flare (≈11→5 m/s) and powered take-off from the snow with a nose tractor prop work on groomed snow.',
  f"Both manoeuvres carry the concept and are untested and only point-mass modelled (no pitch dynamics, flat-plate CN = 1.8·sin α ASSUMED, ToF height at 0.5 m over snow spray). Touchdown KE is not dt-converged: nominal 2.22 → 2.57 → 2.83 J at dt 0.01/0.005/0.0025 s (avail and keMax converge to <0.3 %). A 114 mm nose prop on a glider resting on wing-tip skids needs ≥60 mm ground clearance and will ingest spray on a downhill take-off run; take-off needs ≈1.6 N static thrust ≈30 W ({o['aero']['cRateOn1000mAh']} C from a 1000 mAh 1S pack at −10 °C). Cory & Tedrake perched indoors with motion capture.",
  'Pusher prop on a pylon or above-wing; replace the stall flare by a shallow belly-skid landing with drag skids if tests show flare failures; carry out the listed ≥30-landing test series before any further claims.', 'yes')

f(8, 'major', 'Envelope: wind ≤10 m/s mean, crosswind gusts handled; nominal results robust.',
  f"Wind-seed sweep (12 seeds, same scenario otherwise): nominal avail {sd['nominal']['min']}–{sd['nominal']['max']} % (robust); short {sd['short']['min']}–{sd['short']['max']} %; headwind 6 m/s {sd['headwind']['min']}–{sd['headwind']['max']} % (fails a standard metric in {sd['headwind']['shareFailingAnyStd']*100:.0f} % of seeds); crossgust 6+7 m/s {sd['crossgust']['min']}–{sd['crossgust']['max']} % (fails in {sd['crossgust']['shareFailingAnyStd']*100:.0f} %; sepMax >50 m in 7/12, tdKE >3 J in 4/12); perchwind fails in {sd['perchwind']['shareFailingAnyStd']*100:.0f} %. The concept-specific shotsPerMin ≥2/min passes with skier seed 1 only and fails with 7 of 8 other skier seeds (the default skier seed is favourable; non-harmonised criterion).",
  'State the envelope as mean wind ≤4–6 m/s; report seed distributions (p10) instead of one seed.', 'yes')

f(9, 'minor', 'results.json and design_notes.json numbers for crossgust and perchwind.',
  "Stale: common/env.js was modified at 20:25 after results.json (20:19). Re-run gives crossgust avail 76.1 % (claimed 71.2), endurance 110 min (83), frontShare 57 % (51); perchwind perchSF 1.32 (claimed 1.121), it now takes off once (keMax 13.7 J vs 0, sepMax 96 m vs 246). Pass/fail flags of the 12 harmonised metrics unchanged. All other scenarios reproduce exactly.",
  'Re-run run_all.mjs after shared-model changes and regenerate design_notes.json numbers.', 'yes')

f(10, 'minor', 'Endurance 117 min nominal (≥45 min) with the 3.7 Wh on-board cell + 10 Wh holster bank at −10 °C ×0.75, 10 % reserve.',
  f"Formula reproduced ({en['claimed_min']} min). Camera+ISP at 1.7 W is optimistic for a 50 MP readout + 4K encode + vision tracking (VOXL 2 Mini class 0.5–8 W). With +1.8 W and an 85 % bank→cell transfer: nominal {en['withCam3_5W_min']} min, gentle 6° {en['gentle6deg_withCam3_5W_min']} min, headwind 6 m/s {en['headwind_withCam3_5W_min']} min (FAIL <45). Per run the on-board cell suffices (≈{en['onboardOnlyPerRun']['Wh_nominal_cam3_5']} Wh of {en['onboardOnlyPerRun']['usableOnboardWh']} Wh usable). Charging Li-ion at −10 °C on the lift relies on the self-heating cell (heating energy not counted, ≈0.1 Wh/cycle).",
  'Use a measured power figure for the chosen compute/camera; count bank transfer and heater losses.', 'yes')

f(11, 'minor', 'Capture: active 0.4 m hoop hit 98.9 % at 4 m/s, 99.99 % with the automatic second pass.',
  f"Hit rate depends entirely on the ASSUMED pole-aim scatter σ_lat = 0.035+0.013·v (no data). Re-computed MC: at 5 m/s ×1 {cap['scatterSensitivity']['5']['x1']}, ×1.5 {cap['scatterSensitivity']['5']['x1_5']}, ×2 {cap['scatterSensitivity']['5']['x2']}; at 4 m/s ×2 {cap['scatterSensitivity']['4']['x2']}. A miss costs ~17 s of riding (no standstill) plus another landing 0.7 m from the rider's line. Snatch loads are benign (3.7 N at 4 m/s, 9.2 N at 8 m/s; 39.6 N at 10 m/s when the lanyard bottoms); claws still engaged add ≈{cap['clawsEngagedBreakout_N']} N break-out at {cap['lanyardExtAtBreakout_m']} m stretch – no problem.",
  'Bench-test pole-basket aim with 10 skiers at 2–8 m/s (kill if σ_lat >0.12 m at 5 m/s, as the notes propose).', 'yes')

f(12, 'minor', "Scope: the perch mode is 'borderline' against docs/19 and left to the product owner.",
  "docs/19 excludes '提前沿途放置相机及依赖专用停栖设施的系统。即使由本人预放相机，也按环境机位排除' and keeps '本人携带并自主随行的飞行相机、雪面设备'. Leapfrog is carried by the user, places itself during the run (not in advance, not by hand), uses no dedicated perch facility and is within ≤50 m (nominal) of the rider; perched share is 7.5 % of skiing time nominal, 20–24 % for slow riders. Auditor reading: IN SCOPE as an autonomous accompanying flying camera; R06 differs because it is hand-thrown and static. Caveat: a stranded device (powder, motor failure, perch failure) becomes a left-behind object and must be retrieved by the user, which docs/19 counts in the 'failure recovery burden'.",
  'Product owner to confirm; keep lead-only (V1) as the fallback if perching is ruled out.', 'yes')

f(13, 'minor', 'Regulation: EU C0/A1 with follow-me ≤50 m; US recreational <250 g; VLOS is easier because the device is in front.',
  f"Correct in substance: a privately built <250 g UA may fly in A1; camera → operator registration; follow-me derogation to 50 m from the remote pilot (UAS.OPEN.020(3)). The 50 m limit is exceeded in crossgust (sepMax 53 m) and perchwind (96 m), and in 7/12 crossgust seeds. FAA: recreational <250 g needs no registration/Remote ID but TRUST, CBO guidelines and VLOS of the operator (https://www.faa.gov/uas/recreational_flyers); a lead device in front of the skier is the one aerial layout where VLOS is plausibly kept. Resort bans dominate (LF-05).",
  'Hard-limit separation to 50 m in the controller (land rather than exceed).', 'yes')

f(14, 'minor', 'Usability: 2 actions, 10 s standstill, 2.6 L holster, one gloved hand.',
  "Holster 0.38 × 0.085 × 0.08 m = 2.58 L reproduced; credible only if the fuselage incl. folded prop is ≤0.36 m and the 0.4 m hoop and 0.35 m periscope telescope/fold inside. A 38 cm rigid holster on the hip sits on the chairlift seat edge. Stow at the lift queue (unhook from pole basket, fold two spring-loaded wings, retract hoop and mast, insert) with gloves is more likely 10–15 s than 6 s. The run-out snatch requires the rider to slow to 4–5 m/s on a predictable line – a riding constraint at every run end. Morning/evening USB-C charging of two devices.",
  'Prototype a holster mock-up and time 10 gloved users; consider a back-of-pack sleeve.', 'yes')

f(15, 'minor', 'Aero: Re 50–150 k, L/D 7–12, CLmax 1.0, gravity pays the cruise on ≥15°.',
  f"Re-derived: span {o['aero']['span_m']} m, chord {o['aero']['chord_m']} m, Re = {o['aero']['Re']['8']}–{o['aero']['Re']['14']} at 8–14 m/s (−10 °C) – i.e. 33–66 k, BELOW the brief's 50–150 k band at the slow end. L/D used at operating speed is modest and not inflated: 7.0 at 12 m/s (CL 0.31), 5.4 at 14 m/s; LDmax 11.8 only at 6.9 m/s, just above stall (6.7 m/s) and never used. cd0 0.040 lies inside an audit build-up of 0.030–0.045 (UIUC LSAT airfoil cd 0.015–0.022 at Re 40–60 k, https://m-selig.ae.illinois.edu/uiuc_lsat.html). CLmax 1.0 at Re ≈35 k is at the upper end for a thin folding wing. Glide angle 8.1° at 12 m/s; with L/D −30 % at 14 m/s 14.9° ≈ slope, so the motor fills in (nominal_ld70 motor 2.8 W, still passes). Credible.",
  'Use Re-dependent polars (cd rising below Re 50 k) for slow phases (landing, short turns).', 'yes')

verdict = {
  'crediblePass': [
    'keMax (recomputed harmonised: nominal 13.24 J, short 13.32, max 14.08 J in fast; rider frame within 1.5 m only at launch 1.87 J and capture 1.07 J) – but only at the claimed 125 g',
    'bodyForcePeak 2.7–3.7 N (holster inertia / 4 m/s snatch)', 'handsBusy 0.7 %', 'setupTime/standstill (audit 14–19 s, still ≤30 s)',
    'addedMass 0.25 kg claimed / ≈0.30 kg audit (≤1.5 kg)', 'packVol 2.58 L (tight but plausible)',
    'avail and pxMed in nominal at the claimed sensor (94–96 % over 12 wind seeds, 8 skier seeds)', 'azRange (≥84°)',
    'endurance at nominal power (75–117 min) – fails in headwind with realistic camera power',
    'aero: L/D at operating speed not inflated; gravity pays the cruise on ≥15°',
  ],
  'disputed': [
    {'metric': 'ops', 'scenario': 'all', 'claimed': 2, 'recomputed': 3, 'note': 'stow at the lift is a separate action per criteria.js → FAIL'},
    {'metric': 'jitterRms', 'scenario': 'nominal / short', 'claimed': '1.34 / 2.72 °/s (pass)', 'recomputed': f"footageStability {a('nominal')['footageStability']['subjectRms']} / {a('short')['footageStability']['subjectRms']} °/s = {a('nominal')['jitterPctFramePerS']} / {a('short')['jitterPctFramePerS']} % frame/s", 'note': 'passes the °/s line but ≈2–4× the frame-normalised equivalent of 3 °/s on a chase crop; airframe attitude not modelled'},
    {'metric': 'avail', 'scenario': 'nominal / short', 'claimed': '95.9 / 84.2 %', 'recomputed': f"binned 3072 rows {V['rows3072_binned']['nominal']['avail']} / {V['rows3072_binned']['short']['avail']} %; 0.7 effective {V['rows4300_remosaic']['nominal']['avail']} / {V['rows4300_remosaic']['short']['avail']} %; audit-realistic {V['audit_realistic']['nominal']['avail']} / {V['audit_realistic']['short']['avail']} %", 'note': 'carried by the full-50 MP-readout assumption'},
    {'metric': 'keMax', 'scenario': 'nominal', 'claimed': '13.24 J', 'recomputed': f"{V['mass175_cap15']['nominal']['keMax']} J at an audit mass of 175 g with the same 15 m/s cap (FAIL); 14.7 J with a 13 m/s cap", 'note': 'mass budget understated'},
    {'metric': 'avail', 'scenario': 'crossgust', 'claimed': '71.2 % (results.json, stale)', 'recomputed': f"{m('crossgust','avail')} % rerun; seeds {sd['crossgust']['min']}–{sd['crossgust']['max']} %", 'note': 'fails in 5/12 seeds'},
    {'metric': 'perchSF', 'scenario': 'perchwind', 'claimed': 1.121, 'recomputed': 1.32, 'note': 'stale after env.js change; still below 1.5'},
    {'metric': 'endurance', 'scenario': 'headwind', 'claimed': '52.8 min', 'recomputed': f"{en['headwind_withCam3_5W_min']} min with a 3.5 W camera/compute and 85 % bank transfer (FAIL)", 'note': ''},
    {'metric': 'avail/ops', 'scenario': 'powder (fault)', 'claimed': 'not judged', 'recomputed': f"avail {m('powder','avail')} % FAIL, ops 3 FAIL", 'note': 'soft piste edges are an envelope condition, not a fault'},
    {'metric': 'tdKE', 'scenario': 'nominal', 'claimed': '2.22 J', 'recomputed': '2.57 J (dt/2), 2.83 J (dt/4); >3 J at 175 g', 'note': 'not dt-converged; ASSUMED 3 J line'},
  ],
  'overall': 'NOT FATAL – CONDITIONAL / FRAGILE PASS. Physically sound core (gravity pays a ≤15 m/s lead flight; it is the only concept with a head-on view and keeps VLOS in front of the user). By the shared definitions it fails ops (3 vs ≤2). Its footage and KE passes rest on three optimistic assumptions: a 125 g mass (audit ≈160–175 g), full-resolution 50 MP video readout, and a perfectly stabilised 10 g turret. Load-bearing manoeuvres (perching flare, snow take-off, pole snatch) and resort permission/bystander exposure are unverified. Fixable engineering, not a physics kill; resort acceptance may be the real kill.',
  'envelope': 'Groomed firm (not icy, not soft) piste ≥35 m wide, slope 6–25° (motor-assisted below ~10°), low traffic, mean wind ≤4–6 m/s (crosswind gusts unreliable), rider downhill progress ≈8–11.5 m/s (vTarget ≤13 m/s at a realistic 160–175 g; ≤14 m/s only at the claimed 125 g), only where the resort permits UAS; fallback lead-only mode for faster/slower riders not demonstrated.',
  'summary': 'Original and the most interesting viewpoint of round 2; the metrics claims are reproducible but optimistic in mass, sensor readout and frame-relative jitter, and ops is mis-counted. Recommend: honest BOM, effective-resolution and frame-normalised jitter re-runs, ops=3 or a snatch-to-stow redesign, then a physical perching/take-off test series as the gate.',
}
comp = {
  'aero': {'Re': '33–66 k (8–14 m/s, chord 0.079 m, μ 1.67e-5, ρ 1.0)', 'CLmax': 1.0, 'CD0': 0.04, 'e': 0.8, 'AR': 8.9, 'LDmax': o['aero']['LDmax'], 'LDat12': o['aero']['LD']['12'], 'mass': 0.125, 'massAudit': '0.160–0.175', 'wingArea': 0.055, 'span': 0.70, 'rho': 1.0, 'stallSpeed': o['aero']['vStall'], 'ldSensitivity': 'ldScale 0.7 divides CD (−30 % at every speed)'},
  'battery': {'Wh': '3.7 on board + 10 holster bank (counted)', 'coldDerate': 0.75, 'reserve': 0.10, 'bankTransferEff': 'not modelled (1.0)', 'powerW': {'avionics': 0.75, 'cameraISP': 1.7, 'turret': 0.25, 'servos': 0.2, 'motorMeanNominal': 1.87, 'totalNominal': 4.75}},
  'massBudget': {'claimed_g': {'airframe': 42, 'motorPropESC': 11, 'avionics': 9, 'servos': 10, 'camera': 13, 'turretPeriscope': 10, 'battery': 20, 'hoop': 5, 'margin': 5, 'total': 125},
                 'audit_g': {'airframe': 48, 'motorPropESC': 11, 'avionics': 10, 'actuators': 16, 'cameraAndCompute': '15–20', 'turretPeriscope': '20–25', 'battery': 24, 'hoop': 7, 'wiring': 5, 'total': '≈160–175'},
                 'worn_g': {'claimed': 248, 'audit': '≈300'}},
  'keCap': 'ground speed 15 m/s → 14.06 J at 125 g',
}
json.dump({'concept': 'leapfrog', 'generated': o['generated'], 'evidence': 'audit of a numerical-uncalibrated simulation; not a physical test', 'findings': F, 'verdict': verdict, 'comparability': comp}, open(os.path.join(here, 'part_leapfrog.json'), 'w'), ensure_ascii=False, indent=1)
print('ok', len(F))
